def transform(grid):
 n=len(grid[0]); m=n; center=n//2
 out=[[0]*m for _ in range(m)]
 for r in range(m):
  if r<=center:
   for c in (center-r,center+r): out[r][c]=2
  if r>=3:
   for c in range(m):
    if (c-r)%4==2 and out[r][c]==0: out[r][c]=1
 return out
